SELECT seq, section, check_id, status, expected, observed, detail FROM checks
UNION ALL
SELECT 999, 'OVERALL', 'OVERALL',
       CASE WHEN (SELECT count(*) FROM checks) <> 13 THEN 'FAIL'
            WHEN EXISTS (SELECT 1 FROM checks WHERE status IS NULL OR status NOT IN ('PASS', 'INFO')) THEN 'FAIL' ELSE 'PASS' END,
       'every row PASS (migration 05 verified); 13 rows',
       CASE WHEN (SELECT count(*) FROM checks) <> 13 THEN 'incomplete verification: ' || (SELECT count(*) FROM checks) || ' of 13 check rows'
            ELSE coalesce('failing rows: ' || (SELECT string_agg(check_id, ', ' ORDER BY seq) FROM checks WHERE status IS NULL OR status NOT IN ('PASS', 'INFO')), 'all rows PASS') END,
       CASE WHEN (SELECT count(*) FROM checks) <> 13 OR EXISTS (SELECT 1 FROM checks WHERE status IS NULL OR status NOT IN ('PASS', 'INFO'))
            THEN 'STOP. Do not continue. Save this grid as CSV and send it back.' ELSE 'Verified.' END
ORDER BY seq;
